select case when quantity >= 8 then 'HIGH' else 'LOW' end as quantity_tier, order_id, stddev_samp(quantity) as quantity_stddev, approx_percentile(unit_price, array(0.25, 0.5, 0.75)) as unit_price_quartiles, sum(quantity) as total_quantity, count(*) as cnt from order_items group by grouping sets ((case when quantity >= 8 then 'HIGH' else 'LOW' end, order_id), (case when quantity >= 8 then 'HIGH' else 'LOW' end), ()) having sum(quantity) < 0 order by quantity_tier nulls last;
